20	func TestCommitBatchAppliesAtomicallyInOrder(t *testing.T) {
21		s := openStore(t, tempDir(t))
22	
23		if err := s.Put("keep", []byte("old")); err != nil {
24			t.Fatal(err)
25		}
26		before, err := s.Snapshot()
27		if err != nil {
28			t.Fatal(err)
29		}
30		defer before.Close()
