32		ops := []BatchOp{
33			{Key: "a", Value: []byte("one")},
34			{Key: "b", Value: []byte("two")},
35			{Key: "a", Value: []byte("three")}, // later touch wins inside the batch
36			{Key: "keep", Value: []byte("new")},
37			{Key: "gone", Value: []byte("x")},
38			{Key: "gone", Delete: true}, // put then delete: ends deleted
39			{Key: "del", Value: []byte("y")},
40		}
41		if err := s.Put("del", []byte("y")); err != nil {
42			t.Fatal(err)
43		}
