49		after, err := s.Snapshot()
50		if err != nil {
51			t.Fatal(err)
52		}
53		defer after.Close()
54	
55		// The fixed view taken before sees nothing of the batch.
56		if _, ok := before.Get("a"); ok {
57			t.Fatal("pre-batch snapshot sees batch key")
58		}
59		if got, ok := before.Get("keep"); !ok || string(got) != "old" {
60			t.Fatalf("pre-batch snapshot changed: %q ok=%v", got, ok)
61		}
62	
63		// The view after sees the whole batch, list order resolved.
64		want := map[string]string{"a": "three", "b": "two", "keep": "new"}
65		for k, v := range want {
66			if got, ok := after.Get(k); !ok || string(got) != v {
67				t.Fatalf("post-batch snapshot %s=%q ok=%v, want %q", k, got, ok, v)
68			}
69		}
70		for _, k := range []string{"gone", "del"} {
71			if _, ok := after.Get(k); ok {
72				t.Fatalf("post-batch snapshot sees deleted key %s", k)
73			}
74		}
75		if got, ok, _ := s.Get("a"); !ok || string(got) != "three" {
76			t.Fatalf("latest a: %q ok=%v", got, ok)
77		}
78	}
