97	func TestCommitBatchEmptyAndNoOp(t *testing.T) {
98		dir := tempDir(t)
99		s := openStore(t, dir)
100	
101		size := walSize(t, dir)
102		if err := s.CommitBatch(nil); err != nil {
103			t.Fatalf("empty batch: %v", err)
104		}
105		if err := s.CommitBatch([]BatchOp{}); err != nil {
106			t.Fatalf("empty slice batch: %v", err)
107		}
108		// Only idempotent deletes: commits nothing, log stays untouched.
109		if err := s.CommitBatch([]BatchOp{
