192	// ---- durability and crash atomicity ----
193	
194	func TestCommitBatchDurableAcrossReopen(t *testing.T) {
195		dir := tempDir(t)
196		s := openStore(t, dir)
197		if _, err := s.Snapshot(); err != nil {
198			t.Fatal(err)
199		}
200		if err := s.CommitBatch([]BatchOp{
201			{Key: "a", Value: []byte("1")},
202			{Key: "b", Value: []byte("22")},
203			{Key: "c", Delete: true},
204		}); err != nil {
205			t.Fatal(err)
