214		s2, err := Open(dir)
215		if err != nil {
216			t.Fatal(err)
217		}
218		defer s2.Close()
219		if got, ok, _ := s2.Get("a"); !ok || string(got) != "1" {
220			t.Fatalf("a after reopen: %q ok=%v", got, ok)
221		}
222		if got, ok, _ := s2.Get("b"); !ok || string(got) != "22" {
223			t.Fatalf("b after reopen: %q ok=%v", got, ok)
224		}
225		if got, ok, _ := s2.Get("c"); !ok || string(got) != "live" {
226			t.Fatalf("c after reopen: %q ok=%v", got, ok)
