233	// appendRawFrames writes frames straight to the wal end, bypassing the
234	// commit path, so a crash landing at any point of a batch can be simulated.
235	func appendRawFrames(t *testing.T, dir string, fn func(l *walWriter)) {
236		t.Helper()
237		path := filepath.Join(dir, walName)
238		f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, 0o600)
239		if err != nil {
240			t.Fatal(err)
241		}
242		l := &walWriter{f: f, w: bufio.NewWriter(f)}
243		fn(l)
244		if err := l.w.Flush(); err != nil {
245			t.Fatal(err)
246		}
247		if err := f.Sync(); err != nil {
248			t.Fatal(err)
249		}
250		if err := f.Close(); err != nil {
251			t.Fatal(err)
252		}
253	}
254	
255	func TestCommitBatchTornTailReopensWholeOrNothing(t *testing.T) {
256		dir := tempDir(t)
257		s := openStore(t, dir)
258		// A fully committed batch that must survive.
259		if err := s.CommitBatch([]BatchOp{
260			{Key: "committed", Value: []byte("yes")},
261		}); err != nil {
262			t.Fatal(err)
263		}
264		if _, err := s.Snapshot(); err != nil {
265			t.Fatal(err)
266		}
267		if err := s.Close(); err != nil {
268			t.Fatal(err)
269		}
270	
271		// Killed mid-batch: begin plus one inner frame, no end marker.
272		appendRawFrames(t, dir, func(l *walWriter) {
273			if err := l.encodeFrame(opBatchBegin, "", nil); err != nil {
274				t.Fatal(err)
275			}
276			if err := l.encodeFrameSeq(opPutSeq, "torn", 99, []byte("no")); err != nil {
277				t.Fatal(err)
278			}
279		})
280	
281		s2, err := Open(dir)
282		if err != nil {
283			t.Fatal(err)
284		}
285		if got, ok, _ := s2.Get("committed"); !ok || string(got) != "yes" {
286			t.Fatalf("committed batch lost: %q ok=%v", got, ok)
287		}
288		if _, ok, _ := s2.Get("torn"); ok {
