315	func TestCommitBatchMiscountEndDiscardsBatch(t *testing.T) {
316		dir := tempDir(t)
317		s := openStore(t, dir)
318		if err := s.Put("old", []byte("v0")); err != nil {
319			t.Fatal(err)
320		}
321		if err := s.Close(); err != nil {
322			t.Fatal(err)
323		}
324	
325		// begin + one inner frame + end claiming two inners: not an intact batch.
326		var endVal [metaValueSize]byte
327		binary.LittleEndian.PutUint64(endVal[:], 2)
328		appendRawFrames(t, dir, func(l *walWriter) {
329			if err := l.encodeFrame(opBatchBegin, "", nil); err != nil {
330				t.Fatal(err)
331			}
332			if err := l.encodeFrameSeq(opPutSeq, "bad", 50, []byte("x")); err != nil {
333				t.Fatal(err)
334			}
335			if err := l.encodeFrame(opBatchEnd, "", endVal[:]); err != nil {
336				t.Fatal(err)
337			}
338		})
339	
340		s2, err := Open(dir)
341		if err != nil {
342			t.Fatal(err)
343		}
344		defer s2.Close()
345		if got, ok, _ := s2.Get("old"); !ok || string(got) != "v0" {
346			t.Fatalf("prefix before bad batch lost: %q ok=%v", got, ok)
347		}
348		if _, ok, _ := s2.Get("bad"); ok {
349			t.Fatal("count-mismatched batch was applied")
350		}
