353	func TestCommitBatchFramesOnDisk(t *testing.T) {
354		dir := tempDir(t)
355		s := openStore(t, dir)
356		if err := s.CommitBatch([]BatchOp{
357			{Key: "k", Value: []byte("v")},
358			{Key: "k", Value: []byte("w")},
359		}); err != nil {
360			t.Fatal(err)
361		}
362		if err := s.Close(); err != nil {
363			t.Fatal(err)
364		}
365		data, err := os.ReadFile(filepath.Join(dir, walName))
366		if err != nil {
367			t.Fatal(err)
368		}
369		// A frame begins with the little-endian recordMagic 50 41 4e 53 followed
370		// immediately by its op byte.
371		prefix := func(op byte) []byte { return []byte{0x50, 0x41, 0x4e, 0x53, op} }
372		if !bytes.Contains(data, prefix(opBatchBegin)) || !bytes.Contains(data, prefix(opBatchEnd)) {
373			t.Fatal("wal does not contain batch framing markers")
374		}
375		if bytes.Count(data, prefix(opBatchBegin)) != 1 || bytes.Count(data, prefix(opBatchEnd)) != 1 {
376			t.Fatal("wal does not contain exactly one begin and one end marker")
377		}
