382	func TestCommitBatchSnapshotCursorVisibility(t *testing.T) {
383		s := openStore(t, tempDir(t))
384		if err := s.Put("pre", []byte("0")); err != nil {
385			t.Fatal(err)
386		}
387		cursor, err := s.OpenCursor(Range{})
388		if err != nil {
389			t.Fatal(err)
390		}
391		snap, err := s.Snapshot()
392		if err != nil {
393			t.Fatal(err)
394		}
395	
396		if err := s.CommitBatch([]BatchOp{
397			{Key: "a", Value: []byte("1")},
398			{Key: "b", Value: []byte("2")},
399		}); err != nil {
400			t.Fatal(err)
401		}
402	
403		// The pre-batch cursor pages only the pre-batch view.
404		pages, err := cursor.Page(0, 100)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if len(pages) != 1 || pages[0].Key != "pre" {
409			t.Fatalf("pinned cursor saw the batch: %+v", pages)
410		}
411		if _, ok := snap.Get("a"); ok {
412			t.Fatal("pre-batch snapshot saw the batch")
413		}
414		cursor.Close()
415		snap.Close()
416	
417		// A cursor opened after sees the whole batch.
418		c2, err := s.OpenCursorPrefix("")
419		if err != nil {
420			t.Fatal(err)
421		}
422		defer c2.Close()
423		all, err := c2.Page(0, 100)
424		if err != nil {
425			t.Fatal(err)
426		}
427		if len(all) != 3 {
428			t.Fatalf("new cursor pages %d pairs, want 3: %+v", len(all), all)
429		}
430	}
431	
432	func TestCommitBatchCompactionKeepsIntraBatchOrder(t *testing.T) {
433		dir := tempDir(t)
434		s := openStore(t, dir)
435	
436		if err := s.Put("k", []byte("v1")); err != nil {
437			t.Fatal(err)
438		}
439		// This cursor pins v1; the batch then touches k three times. Its middle
440		// value was never visible to any whole-batch view and is reclaimable, but
441		// the retained pair (pinned v1, post-batch head v3) must survive the log
442		// rewrite linked oldest-to-newest in the right order.
443		cursor, err := s.OpenCursorPrefix("")
444		if err != nil {
445			t.Fatal(err)
446		}
447		if err := s.CommitBatch([]BatchOp{
448			{Key: "k", Value: make([]byte, 4096)},
449			{Key: "k", Value: []byte("middle")},
450			{Key: "k", Value: []byte("v3")},
451			{Key: "other", Value: []byte("o1")},
452			{Key: "other", Value: []byte("o2")},
453		}); err != nil {
454			t.Fatal(err)
455		}
456		if err := s.Compact(); err != nil {
457			t.Fatalf("compact after batch: %v", err)
458		}
459		if got, ok, _ := s.Get("k"); !ok || string(got) != "v3" {
460			t.Fatalf("k after compact: %q ok=%v", got, ok)
461		}
462		if got, ok, _ := s.Get("other"); !ok || string(got) != "o2" {
463			t.Fatalf("other after compact: %q ok=%v", got, ok)
464		}
465		pinned, err := cursor.Page(0, 10)
466		if err != nil {
467			t.Fatal(err)
468		}
469		if len(pinned) != 1 || string(pinned[0].Value) != "v1" {
470			t.Fatalf("pinned cursor changed: %+v", pinned)
471		}
472		cursor.Close()
473		if err := s.Close(); err != nil {
474			t.Fatal(err)
475		}
476	
477		// Replay the compacted log: retained per-key histories must survive in
478		// ascending sequence order, with no seq duplicated or reordered.
479		s2, err := Open(dir)
480		if err != nil {
481			t.Fatal(err)
482		}
483		defer s2.Close()
484		if got, ok, _ := s2.Get("k"); !ok || string(got) != "v3" {
485			t.Fatalf("k after reopen: %q ok=%v", got, ok)
486		}
487		chains, values := replayChains(t, dir)
488		if seqs := chains["k"]; len(seqs) != 2 {
489			t.Fatalf("k retained history after compaction: %v, want 2 versions", seqs)
490		} else if seqs[0] >= seqs[1] {
491			t.Fatalf("batch versions split or reordered in compacted log: %v", seqs)
492		}
493		if values[keySeq{"k", chains["k"][0]}] != "v1" || values[keySeq{"k", chains["k"][1]}] != "v3" {
494			t.Fatalf("retained values mismatch: %+v", values)
495		}
496	}
497	
498	type keySeq struct {
499		key string
500		seq uint64
501	}
502	
503	func replayChains(t *testing.T, dir string) (map[string][]uint64, map[keySeq]string) {
504		t.Helper()
505		chains := make(map[string][]uint64)
506		values := make(map[keySeq]string)
507		seen := make(map[uint64]bool)
508		_, _, err := replayWAL(dir, func(op byte, key string, value []byte, seq uint64) {
509			switch op {
510			case opPutSeq, opDeleteSeq:
511				if seen[seq] {
512					t.Fatalf("duplicate seq %d on key %q during replay", seq, key)
513				}
514				seen[seq] = true
515				chains[key] = append(chains[key], seq)
516				if op == opPutSeq {
517					values[keySeq{key, seq}] = string(value)
518				}
519			}
520		})
521		if err != nil {
522			t.Fatal(err)
523		}
524		return chains, values
525	}
