	base := s.current.Load()
	// Flatten at most once, before the group: once a queued batch walked a
	// key down the overlay chain it is cached in head, so lookups never
	// re-walk it. Re-flattening inside the loop copied the whole live
	// keyspace every viewFlattenLimit queued batches; peak temporary memory
	// grew with live keys times the queued count. Now at most a constant
	// number of live-key-sized maps exists regardless of the queue length.
	if base.depth >= viewFlattenLimit {
		base = base.flatten()
	}
	seq := s.nextSeq
	plans := make([]commitPlan, 0, len(group))
	encodedAny := false
	var groupDirty []string

	// head caches the group-cumulative terminal node of every key the queued
	// batches touch. It is sized by the batches' distinct keys, never by the
	// live keyspace, so a thousand-key store behind a long queue costs one
	// map entry per touched key rather than one keyspace copy per 64
	// batches. groupAbsent marks a key resolved as absent in base.
	head := make(map[string]*node)
	// term is an optional flat accumulator of the state after the whole
	// group, kept only when the group's overlays would themselves grow past
	// viewFlattenLimit; it is published as one depth-1 view so post-group
	// reads and the next group never inherit a queue-length overlay chain.
	var term map[string]*node
	keepFlat := base.depth+len(group) > viewFlattenLimit

	resolve := func(key string) *node {
		n, ok := head[key]
		if ok {
			if n == groupAbsent {
				return nil
			}
			return n
		}
		n = base.lookup(key)
		if n == nil {
			head[key] = groupAbsent
		} else {
			head[key] = n
		}
		return n
	}

	for _, p := range group {
		// Each batch gets its own thin immutable overlay on the previous
		// batch's overlay, so the view it publishes is a valid point-in-time
		// state independent of later batches, and queued batches cost memory
		// proportional to their own ops rather than the whole live keyspace.
		v := newView(base)
		var changes []batchChange
		for i := range p.ops {
			op := &p.ops[i]
			headNode := resolve(op.Key)
			if op.Delete {
				if headNode == nil || !headNode.present {
					continue // idempotent no-op, matching the single Delete
				}
				seq++
				nn := &node{present: false, seq: seq, older: headNode}
				changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
				v.keys[op.Key] = nn
				head[op.Key] = nn
				if term != nil {
					term[op.Key] = nn
				}
			} else {
				seq++
				value := cloneBytes(op.Value)
				nn := &node{value: value, present: true, seq: seq, older: headNode}
				changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
				v.keys[op.Key] = nn
				head[op.Key] = nn
				if term != nil {
					term[op.Key] = nn
				}
			}
		}
		if len(changes) > 0 {
			if err := s.wal.encodeBatch(changes); err != nil {
				return rollback(err)
			}
			encodedAny = true
			if term == nil && keepFlat {
				// Lazily seed the flat accumulator from the complete state so
				// far (base plus every earlier batch in the group); every
				// later change updates it as it is applied.
				term = make(map[string]*node)
				v.rangeEach(func(k string, n *node) bool {
					term[k] = n
					return true
				})
			}
			for i := range changes {
				groupDirty = append(groupDirty, changes[i].key)
			}
		}
		var planView *view
		if len(changes) > 0 {
			planView = v
		}
		plans = append(plans, commitPlan{view: planView})
		base = v
	}

	if encodedAny {
		// One flush, one fsync for the whole group. Return means every
		// encoded batch in it is durable as a self-contained framed commit.
		if err := s.wal.flushSync(); err != nil {
			return rollback(err)
		}
	}

	s.nextSeq = seq
	for i, plan := range plans {
		if plan.view != nil {
			s.current.Store(plan.view)
			plans[i].view = nil // release intermediate views as soon as published
		}
	}
	// Re-flatten the final state when the group's overlay chain would
	// otherwise be as deep as the queue, so read depth and the next group's
	// baseline stay bounded by viewFlattenLimit, not by queue length.
	if term != nil {
		s.current.Store(&view{keys: term, base: nil, depth: 1})
	}
	s.dirty = dedupeKeys(s.dirty, groupDirty)
