package snapshot

import (
	"bufio"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"sort"
)

// Hot backup and restore.
//
// A backup exports the store's complete committed state at one fixed commit
// watermark as a portable, segmented artifact. The export anchors to the
// current view and then streams its live entries into self-describing,
// checksummed segments without holding the store's write lock: writes,
// deletes, batch commits, snapshots, cursor paging, checkpoints and
// compactions proceed concurrently and never block on the disk writes the
// backup performs. Reads keep hitting memory exactly as before.
//
// Artifact layout, inside the output directory:
//
//	backup.tmp/                staging area while an export runs
//	  segment-XXXXX.dat        one segment, fully synced, then renamed up
//	  manifest.dat.tmp         the manifest, built last, renamed last
//	segment-XXXXX.dat          finished segments
//	manifest.dat               present only when the whole export finished
//
// The artifact is complete if and only if manifest.dat is present, intact and
// names exactly the segments that exist; Restore rejects anything short of
// that wholesale with fs.ErrInvalid. A kill at any instant therefore leaves
// either the previous contents of the directory or one complete artifact;
// staging debris and an orphaned manifest are swept at the start of the next
// backup or the next Open of a directory that contains it.
//
// Segment file layout (all integers little-endian):
//
//	magic      uint32   backupMagic
//	version    uint32   backupVersion
//	watermark  uint64   highest commit sequence exported
//	snapshots  uint64   cumulative snapshot count at the export watermark
//	index      uint32   segment position, starting at 0
//	count      uint32   number of entries in this segment
//	cumulative uint64   cumulative live-entry count through this segment
//	entries    [count]entry
//	crc        uint32   IEEE CRC-32 of every preceding byte of the file
//
// One entry is a flags byte (0 = put, 1 = tombstone), a uint32 key length, a
// uint32 value length, the entry's commit sequence (uint64), the key, then
// the value. Entries are written in ascending key order; a put carries its
// value bytes, a tombstone carries none.
//
// The manifest repeats the artifact-level fields (magic, version, watermark,
// snapshots, total entry count, segment count) and one record per segment
// (its index, entry count, cumulative count and content CRC), terminated by
// an overall CRC. A segment is accepted only when its own CRC verifies and
// every field the manifest records about it matches: a missing segment, a
// truncated segment, a checksum mismatch, an unknown version or a manifest
// that disagrees with the files rejects the entire artifact.
const (
	backupDirName = "" // artifacts live directly in the caller's output dir

	backupStageDir    = "backup.tmp"
	backupManifest    = "manifest.dat"
	backupManifestTmp = "manifest.dat.tmp"
	backupSegmentPref = "segment-"
	backupSegmentSufx = ".dat"

	backupMagic   uint32 = 0x42414b53 // bytes "SKAB"
	backupVersion uint32 = 1

	// backupSegHeaderSize is magic, version, watermark, snapshots, index,
	// count, cumulative.
	backupSegHeaderSize = 4 + 4 + 8 + 8 + 4 + 4 + 8
	// backupManifestSize is magic, version, watermark, snapshots, total
	// entries, segment count, followed by the terminal overall CRC.
	backupManifestSize = 4 + 4 + 8 + 8 + 8 + 4
	// backupSegRecSize is one manifest per-segment record: index, count,
	// cumulative, content CRC.
	backupSegRecSize = 4 + 4 + 8 + 4
	// backupEntriesPerSegment bounds how much of the live keyspace one
	// segment holds; the export streams the entries through a buffer this
	// size and never materializes the whole keyspace to write it. It is a
	// write chunking target, not a format limit.
	backupEntriesPerSegment = 4096
)

// errBackupInvalid wraps fs.ErrInvalid for every malformed artifact or bad
// path argument.
func errBackupInvalid(msg string) error {
	return errors.Join(errors.New("snapshot: "+msg), errInvalid())
}

// errInvalid returns the shared fs.ErrInvalid wrapper; defined here so the
// backup code has one call site (errors.go owns the canonical sentinels).
func errInvalid() error { return errNotDir }

// backupAnchor is the fixed point-in-time state an export streams. It is
// captured under the store lock and is itself immutable afterwards: the view
// is never mutated after publication, so the streaming that follows takes no
// lock and cannot observe commits made after the anchor.
type backupAnchor struct {
	view      *view
	watermark uint64 // highest commit sequence covered
	snaps     uint64 // cumulative snapshot count covered
}

// backupEntry is one live key state in export order.
type backupEntry struct {
	key     string
	value   []byte
	seq     uint64
	present bool
}

// Backup exports the store's complete committed state into outDir as a
// portable, segmented backup anchored at the commit watermark current when
// Backup anchors. Writes and deletes committed after the anchor are not
// included and proceed concurrently without blocking; every lock-free read
// keeps hitting memory and is not held up by the export's disk writes.
//
// The export is all-or-nothing: segment files are built and synced in a
// staging directory and promoted one at a time; the manifest is written last
// and only becomes visible once every segment it names is durable. A process
// killed at any point leaves no half artifact in outDir — staging debris is
// swept at the start of the next Backup there (or the next Open of that
// directory) and never affects the store being backed up.
//
// A path that does not exist or is not a directory, or an existing directory
// that already contains a complete or partial artifact, is rejected with an
// error wrapping fs.ErrInvalid. Backup on a closed store returns an error
// wrapping fs.ErrClosed.
func (s *Store) Backup(outDir string) error {
	if s.closed.Load() {
		return errStoreClosed
	}
	if outDir == "" {
		return errBackupInvalid("backup output path is empty")
	}

	// Prepare the output directory and clear any debris from an export killed
	// mid-run, before touching the store. An existing complete artifact (a
	// live manifest) or unrelated finished segments are not overwritten.
	info, err := os.Stat(outDir)
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		if err := os.MkdirAll(outDir, 0o700); err != nil {
			return err
		}
	} else if !info.IsDir() {
		return errBackupInvalid("backup output path is not a directory")
	}
	if err := prepareBackupDir(outDir); err != nil {
		return err
	}

	// Anchor at one fixed watermark. This is the only moment the export takes
	// the write lock; everything after it streams from an immutable view.
	s.mu.Lock()
	if s.closed.Load() {
		s.mu.Unlock()
		return errStoreClosed
	}
	anchor := backupAnchor{
		view:      s.current.Load(),
		watermark: s.nextSeq,
		snaps:     s.snapshots.Load(),
	}
	s.mu.Unlock()

	return writeBackup(outDir, anchor)
}

// prepareBackupDir makes outDir an empty target for a fresh artifact: it
// removes staging debris from an interrupted export and refuses to overwrite
// any finished artifact. It also sweeps a stray manifest temp.
func prepareBackupDir(outDir string) error {
	entries, err := os.ReadDir(outDir)
	if err != nil {
		return err
	}
	var hasArtifact bool
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			if name != backupStageDir {
				// Leave foreign directories alone but do not export on top of
				// a non-empty, non-artifact directory.
				return errBackupInvalid("backup output directory is not empty")
			}
			continue
		}
		if name == backupManifest {
			hasArtifact = true
			continue
		}
		if isBackupSegmentName(name) || name == backupManifestTmp {
			continue // orphaned by a kill; swept below
		}
		return errBackupInvalid("backup output directory is not empty")
	}
	if hasArtifact {
		return errBackupInvalid("backup output directory already holds a backup")
	}
	// Remove all leftover staging and orphaned segment/manifest files.
	if err := os.RemoveAll(filepath.Join(outDir, backupStageDir)); err != nil {
		return err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if isBackupSegmentName(name) || name == backupManifestTmp {
			if err := os.Remove(filepath.Join(outDir, name)); err != nil &&
				!errors.Is(err, os.ErrNotExist) {
				return err
			}
		}
	}
	return syncDirectory(outDir)
}

// isBackupSegmentName reports whether name is a finished segment file name.
func isBackupSegmentName(name string) bool {
	return len(name) > len(backupSegmentPref)+len(backupSegmentSufx) &&
		name[:len(backupSegmentPref)] == backupSegmentPref &&
		name[len(name)-len(backupSegmentSufx):] == backupSegmentSufx
}

// segmentName renders a segment index as a fixed-width, zero-padded name.
func segmentName(index uint32) string {
	const digits = "0123456789"
	buf := make([]byte, 10)
	n := index
	for i := len(buf) - 1; i >= 0; i-- {
		buf[i] = digits[n%10]
		n /= 10
	}
	return backupSegmentPref + string(buf) + backupSegmentSufx
}

// writeBackup streams the anchor's live entries into segments and finishes
// with the manifest. It holds no store lock: the anchored view is immutable.
func writeBackup(outDir string, anchor backupAnchor) (err error) {
	stage := filepath.Join(outDir, backupStageDir)
	if err := os.MkdirAll(stage, 0o700); err != nil {
		return err
	}
	cleanup := func() {
		os.RemoveAll(stage)
		// Best effort: remove any segment promoted before a failure.
		if entries, rerr := os.ReadDir(outDir); rerr == nil {
			for _, e := range entries {
				if !e.IsDir() && isBackupSegmentName(e.Name()) {
					os.Remove(filepath.Join(outDir, e.Name()))
				}
			}
			os.Remove(filepath.Join(outDir, backupManifestTmp))
		}
		_ = syncDirectory(outDir)
	}

	// Collect entries lazily in ascending key order, a chunk at a time. The
	// anchored view is walked once; at most one chunk plus the small set of
	// overlay keys the range walk needs is ever resident.
	ch := make(chan []backupEntry, 1)
	walkerDone := make(chan error, 1)
	go func() {
		walkerDone <- streamAnchorEntries(anchor.view, ch)
	}()

	type segInfo struct {
		index      uint32
		count      uint32
		cumulative uint64
		crc        uint32
	}
	var segments []segInfo
	var total uint64
	var index uint32

	for chunk := range ch {
		// A chunk is already sorted by the walker.
		rec := segInfo{index: index, count: uint32(len(chunk)), cumulative: total + uint64(len(chunk))}
		crc, werr := writeSegment(stage, index, anchor, rec.cumulative, chunk)
		if werr != nil {
			cleanup()
			return werr
		}
		rec.crc = crc
		// Promote the finished segment out of staging only after it is fully
		// synced, so a crash never exposes a partial final file under a
		// finished name; without the manifest the lone file is debris.
		from := filepath.Join(stage, segmentName(index))
		to := filepath.Join(outDir, segmentName(index))
		if err := os.Rename(from, to); err != nil {
			cleanup()
			return err
		}
		if err := syncDirectory(outDir); err != nil {
			cleanup()
			return err
		}
		segments = append(segments, rec)
		total = rec.cumulative
		index++
	}
	if werr := <-walkerDone; werr != nil {
		cleanup()
		return werr
	}

	// The manifest is the commit point: it names exactly the durable segment
	// set and carries the artifact-level metadata. Build it in staging, sync,
	// then rename into place and force the directory.
	if err := writeManifest(stage, outDir, anchor, total, segments); err != nil {
		cleanup()
		return err
	}
	if err := os.RemoveAll(stage); err != nil {
		return err
	}
	return syncDirectory(outDir)
}

// streamAnchorEntries walks the immutable view once and sends its terminal
// entries in ascending key order, at most backupEntriesPerSegment per chunk.
// Tombstones are included so a restored store reproduces deletions; keys that
// never existed never appear.
func streamAnchorEntries(v *view, ch chan<- []backupEntry) error {
	// Gather keys from every overlay with one pass (rangeEach already dedups
	// terminal versions), then sort. The key slice is the one unavoidable
	// O(live keys) index; the values themselves are streamed, not copied.
	var keys []string
	v.rangeEach(func(k string, n *node) bool {
		keys = append(keys, k)
		return true
	})
	sort.Strings(keys)

	chunk := make([]backupEntry, 0, backupEntriesPerSegment)
	flush := func() error {
		if len(chunk) == 0 {
			return nil
		}
		ch <- chunk
		chunk = make([]backupEntry, 0, backupEntriesPerSegment)
		return nil
	}
	for _, k := range keys {
		n := v.lookup(k)
		if n == nil {
			continue
		}
		e := backupEntry{key: k, seq: n.seq, present: n.present}
		if n.present {
			// Copy the bytes: the writer fully consumes the chunk before the
			// next one is produced, and node values are immutable, but copy so
			// the export never aliases caller-owned memory semantics.
			e.value = cloneBytes(n.value)
		}
		chunk = append(chunk, e)
		if len(chunk) == backupEntriesPerSegment {
			flush()
		}
	}
	if len(chunk) > 0 {
		ch <- chunk
	}
	close(ch)
	return nil
}

// writeSegment serializes one segment file in dir, fully synced, and returns
// its content CRC (the terminal checksum it carries).
func writeSegment(dir string, index uint32, anchor backupAnchor, cumulative uint64, entries []backupEntry) (uint32, error) {
	path := filepath.Join(dir, segmentName(index))
	tmp, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return 0, err
	}
	fail := func(err error) (uint32, error) {
		tmp.Close()
		os.Remove(path)
		return 0, err
	}

	w := bufio.NewWriter(tmp)
	head := make([]byte, backupSegHeaderSize)
	binary.LittleEndian.PutUint32(head[0:4], backupMagic)
	binary.LittleEndian.PutUint32(head[4:8], backupVersion)
	binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
	binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
	binary.LittleEndian.PutUint32(head[24:28], index)
	binary.LittleEndian.PutUint32(head[28:32], uint32(len(entries)))
	binary.LittleEndian.PutUint64(head[32:40], cumulative)

	h := crc32.NewIEEE()
	if _, err := w.Write(head); err != nil {
		return fail(err)
	}
	h.Write(head)

	ehdr := make([]byte, checkpointEntrySize)
	for _, e := range entries {
		if len(e.key) > maxRecord || len(e.value) > maxRecord {
			return fail(errors.New("snapshot: backup entry too large"))
		}
		if e.present {
			ehdr[0] = ckptFlagPut
		} else {
			ehdr[0] = ckptFlagDelete
		}
		binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(e.key)))
		binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(e.value)))
		binary.LittleEndian.PutUint64(ehdr[9:17], e.seq)
		if _, err := w.Write(ehdr); err != nil {
			return fail(err)
		}
		h.Write(ehdr)
		if _, err := io.WriteString(w, e.key); err != nil {
			return fail(err)
		}
		h.Write([]byte(e.key))
		if len(e.value) > 0 {
			if _, err := w.Write(e.value); err != nil {
				return fail(err)
			}
			h.Write(e.value)
		}
	}

	crc := h.Sum32()
	var crcb [crcSize]byte
	binary.LittleEndian.PutUint32(crcb[:], crc)
	if _, err := w.Write(crcb[:]); err != nil {
		return fail(err)
	}
	if err := w.Flush(); err != nil {
		return fail(err)
	}
	if err := tmp.Sync(); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(path)
		return 0, err
	}
	return crc, nil
}

// manifestInfo is the validated content of manifest.dat.
type manifestInfo struct {
	watermark uint64
	snaps     uint64
	total     uint64
	segments  []manifestSegment
}

type manifestSegment struct {
	index      uint32
	count      uint32
	cumulative uint64
	crc        uint32
}

// writeManifest builds and durably installs the manifest, the export's commit
// point. It is written under a temp name in the staging directory, synced,
// renamed into outDir and followed by a directory force.
func writeManifest(stage, outDir string, anchor backupAnchor, total uint64, segs []struct {
	index      uint32
	count      uint32
	cumulative uint64
	crc        uint32
}) error {
	if err := os.MkdirAll(stage, 0o700); err != nil {
		return err
	}
	tmpPath := filepath.Join(stage, backupManifestTmp)
	tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return err
	}
	fail := func(err error) error {
		tmp.Close()
		os.Remove(tmpPath)
		return err
	}

	w := bufio.NewWriter(tmp)
	head := make([]byte, backupManifestSize)
	binary.LittleEndian.PutUint32(head[0:4], backupMagic)
	binary.LittleEndian.PutUint32(head[4:8], backupVersion)
	binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
	binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
	binary.LittleEndian.PutUint64(head[24:32], total)
	binary.LittleEndian.PutUint32(head[32:36], uint32(len(segs)))
	h := crc32.NewIEEE()
	if _, err := w.Write(head); err != nil {
		return fail(err)
	}
	h.Write(head)

	rec := make([]byte, backupSegRecSize)
	for _, s := range segs {
		binary.LittleEndian.PutUint32(rec[0:4], s.index)
		binary.LittleEndian.PutUint32(rec[4:8], s.count)
		binary.LittleEndian.PutUint64(rec[8:16], s.cumulative)
		binary.LittleEndian.PutUint32(rec[16:20], s.crc)
		if _, err := w.Write(rec); err != nil {
			return fail(err)
		}
		h.Write(rec)
	}
	var crcb [crcSize]byte
	binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
	if _, err := w.Write(crcb[:]); err != nil {
		return fail(err)
	}
	if err := w.Flush(); err != nil {
		return fail(err)
	}
	if err := tmp.Sync(); err != nil {
		return fail(err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpPath)
		return err
	}
	if err := os.Rename(tmpPath, filepath.Join(outDir, backupManifest)); err != nil {
		os.Remove(tmpPath)
		return err
	}
	return syncDirectory(outDir)
}

