// One index pass over the immutable view yields the sorted terminal keys,
// exactly as opening a cursor materializes its ordered key list. Values
// are not collected here; they are read and written a chunk at a time
// below, so the whole keyspace is never resident before hitting disk.
var keys []string
anchor.view.rangeEach(func(k string, _ *node) bool {
	keys = append(keys, k)
	return true
})
sort.Strings(keys)

var segments []manifestSegment
var total uint64
var index uint32

for start := 0; start < len(keys); start += backupEntriesPerSegment {
	stop := start + backupEntriesPerSegment
	if stop > len(keys) {
		stop = len(keys)
	}
	entries := make([]backupEntry, 0, stop-start)
	for _, k := range keys[start:stop] {
		n := anchor.view.lookup(k)
		if n == nil {
			continue
		}
